from abc import ABCMeta, abstractmethod
from functools import wraps
from .commands import QuantaConfigModeCommand, DellConfigModeCommand

import logging
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def reconnect_cli_before_executing(func):
    """ Decorate func so that it reconnects self._cli before running.

    This aims to make sure that the remote shell that the method uses is in
    clear state.
    """
    @wraps(func)
    def reconnecting_closure(self, *args, **kwargs):
        self._cli.disconnect()
        self._cli.connect()
        self._read_until_prompt()
        return func(self, *args, **kwargs)
    return reconnecting_closure


class Switch(object):
    __metaclass__ = ABCMeta
    mode_command_type = None
    prompt = '#'

    def __init__(self, cli):
        cls_name = self.__class__.__name__
        logger.debug("Creating new switch instance: '{}'.".format(cls_name))
        self._cli = cli
        self._config_mode = self.mode_command_type(cli)

    def _read_until_prompt(self):
        return self._cli.expect_exact(self.prompt)

    @reconnect_cli_before_executing
    def enable_interface(self, interface_id):
        """ Activate a physical interface.

        :param interface_id:
            Interface ID as given to the "shutdown" command (e.g. '1/26').
        :type interface_id: ``str``
        """
        self._change_interface_state(interface_id, enabled=True)

    @reconnect_cli_before_executing
    def disable_interface(self, interface_id):
        """ Mark a physical interface as unavailable for traffic.

        :param interface_id:
            Interface ID as given to the "shutdown" command (e.g. '1/26').
        :type interface_id: ``str``
        """
        self._change_interface_state(interface_id, enabled=False)

    @abstractmethod
    def _change_interface_state(self, interface_id, enabled):
        raise NotImplementedError

    @abstractmethod
    def interface_active(self, interface_id):
        """ Get the state of the interface (whether it is enabled or not).

        :param interface_id:
            Interface ID as given to the "shutdown" command (e.g. '1/26').
        :type interface_id: ``str``
        :returns: True if interface is enabled, false otherwise.
        :rtype: ``bool``
        """
        raise NotImplementedError


class Quanta(Switch):
    """ Interface implementation for Quanta switches.

    Tested on Quanta T3048-LY8, with Runtime Code 2.4.11.00.

    :param cli:
        A remote shell through which the instance should communicate with the
        switch.
    :type cli: ``RemoteShell``
    """
    mode_command_type = QuantaConfigModeCommand

    # TODO: Implement commands as send/expect machines

    # TODO: interface mode command, when implemented as a context manager,
    # should check the output for errors (e.g. bad interface), otherwise it may
    # send too many exit commands.

    def _change_interface_state(self, interface_id, enabled):
        with self._config_mode():
            self._cli.sendline('interface {}'.format(interface_id))
            output = self._read_until_prompt()
            self._check_output_for_error_message(output)

            self._cli.sendline('no shutdown' if enabled else 'shutdown')

            self._cli.sendline('exit')

    @reconnect_cli_before_executing
    def interface_active(self, interface_id):
        self._cli.sendline('show interface status {}'.format(interface_id))
        output = self._read_until_prompt()

        self._check_output_for_error_message(output)
        line = self._get_admin_mode_line(output)
        if not line:
            raise RuntimeError("Unrecognized output: {}".format(output))
        return self._parse_admin_mode_line(line)

    @staticmethod
    def _check_output_for_error_message(output):
        if ("An invalid interface has been used for this command." in output or
                "The specified interface does not exist." in output):
            raise RuntimeError("invalid interface given.")

    @staticmethod
    def _get_admin_mode_line(output):
        # Example admin mode line:
        # Admin Mode........................ Disable\r\n
        first_char_idx = output.find('Admin Mode')
        last_char_idx = output.find('\r\n', first_char_idx)
        if first_char_idx == -1 or last_char_idx == -1:
            return None
        return output[first_char_idx:last_char_idx]

    @staticmethod
    def _parse_admin_mode_line(line):
        if line.endswith('Enable'):
            return True
        if line.endswith('Disable'):
            return False
        exc_msg = "Unrecognized admin mode line content: {0!r}".format(line)
        raise RuntimeError(exc_msg)


class Dell(Switch):
    """ Interface implementation for Dell switches.

    Tested on Dell S4048-ON, with Application Software Version 9.11(2.1)

    Requires the default mode after logging on to the switch to be "EXEC".
    To achieve this, one can use the following command:

    aaa authorization exec default tacacs+ local if-authenticated

    Consult command reference before executing it.

    :param cli:
        A remote shell through which the instance should communicate with the
        switch.
    :type cli: ``RemoteShell``
    """
    # TODO: unittests

    # TODO: Implement commands as send/expect machines

    # TODO: interface mode command, when implemented as a context manager,
    # should check the output for errors (e.g. bad interface), otherwise it may
    # send too many exit commands.
    mode_command_type = DellConfigModeCommand

    def _change_interface_state(self, interface_id, enabled):
        interface_type = self._get_interface_type(interface_id)
        with self._config_mode():
            mode_cmd = 'interface {} {}'.format(interface_type, interface_id)
            self._cli.sendline(mode_cmd)
            self._cli.sendline('no shutdown' if enabled else 'shutdown')
            self._cli.sendline('exit')

    @reconnect_cli_before_executing
    def interface_active(self, interface_id):
        interface_type = self._get_interface_type(interface_id)

        show_cmd = 'show ip interface brief {} {}'.format(interface_type,
                                                          interface_id)
        self._cli.sendline(show_cmd)
        output = self._read_until_prompt()
        show_line = output.split('\r\n')[2]
        segments = show_line.split()
        state_str = segments[-2]
        return True if state_str == 'up' else False

    def _get_interface_type(self, interface_id):
        self._cli.sendline('terminal length 0')
        self._read_until_prompt()
        self._cli.sendline('show ip interface brief')

        output = self._read_until_prompt()
        lines = output.split('\r\n')
        matching_lines = list(filter(lambda line: interface_id in line, lines))
        if not matching_lines:
            raise RuntimeError('invalid interface id.')
        interface_type = matching_lines[0].split()[0]
        return interface_type
